window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['bigdata-3']={"round":3,"cert":"bigdata","questions":[{"id":"6a67532b1bbde79cd2c1c8aa","number":1,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>소셜 데이터, 이미지, 오디오와 같은 비정형 데이터를 저장하는 데 주로 활용되며, 아파치 재단의 Cassandra가 대표적인 예로 꼽히는 시스템은 무엇인가?</p>","choices":[{"n":1,"html":"Grid"},{"n":2,"html":"RDB"},{"n":3,"html":"Legacy"},{"n":4,"html":"NoSQL"}],"answer":[4]},{"id":"6a67532a1bbde79cd2c1c8a1","number":2,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석 마스터 플랜(로드맵)을 수립할 때 고려해야 할 사항으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"단계적 세부 이행 계획을 수립할 때는 일반적으로 WBS(Work Breakdown Structure)를 활용한다."},{"n":2,"html":"데이터 분석 프로젝트 수행에 필요한 하드웨어 및 소프트웨어 비용, 인건비 등의 소요 비용은 로드맵 수립 시점이 아닌 추후에 고려한다."},{"n":3,"html":"로드맵 수립 시 데이터 분석 과제의 전략적 중요도, 비즈니스 성과 및 ROI, 분석 과제의 실행 용이성을 우선적으로 고려한다."},{"n":4,"html":"마스터 플랜 수립을 위해 분석대상 과제 정의(도출), 우선순위 평가, 단계적 세부 이행 계획 수립, 중장기적 로드맵 작성의 절차를 거치게 된다."}],"answer":[2]},{"id":"6a67532a1bbde79cd2c1c89d","number":3,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 보기 가운데 개인정보에 해당한다고 보기 가장 어려운 것은?</p>","choices":[{"n":1,"html":"종교, 사상, 신조, 정치적 성향, 가치관 등 내면의 비밀"},{"n":2,"html":"홍채, 지문, DNA 등 생체인식정보"},{"n":3,"html":"영화감상, 독서, 악기 연주와 같은 개인의 취미생활"},{"n":4,"html":"주민등록번호, 성명, 주소, 본적, 본관, 가족관계 등 신분관계"}],"answer":[3]},{"id":"6a67532a1bbde79cd2c1c89b","number":4,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>원천 데이터 소스에서 데이터를 뽑아내고, 분석하기 쉬운 형태로 변환한 뒤, 그 결과 데이터를 목표 시스템에 적재하는 역할을 수행하는 핵심 구성요소(기술 및 도구)는 무엇인가?</p>","choices":[{"n":1,"html":"ETL"},{"n":2,"html":"DBMS"},{"n":3,"html":"Data Suppression"},{"n":4,"html":"Data Integration"}],"answer":[1]},{"id":"6a67532a1bbde79cd2c1c8a7","number":5,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 보기 가운데 데이터 비식별화 기법에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"데이터 마스킹(Data Masking)"},{"n":2,"html":"가명처리(Pseudonymization)"},{"n":3,"html":"범주화(Suppression)"},{"n":4,"html":"데이터값 대체(Data Substitution)"}],"answer":[4]},{"id":"6a67532a1bbde79cd2c1c89a","number":6,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 과학자(Data Scientist)가 갖추어야 할 기본 소양으로 보기 어려운 것은?</p>","choices":[{"n":1,"html":"업무와 데이터에 대한 통찰 역량"},{"n":2,"html":"최적의 모델 인자를 구성해 내는 특징공학(Feature Engineering) 역량"},{"n":3,"html":"데이터베이스 관리 시스템을 구축하는 역량"},{"n":4,"html":"빅데이터 분석에 필요한 제반 기술적 역량"}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8a9","number":7,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 전처리 단계에서 이루어지는 데이터 스케일링(Data Scaling)에 관한 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"데이터를 표준화하거나 정규화한다."},{"n":2,"html":"데이터 스케일링을 수행하면 각 변수가 동일한 조건(또는 범위)을 갖게 되어, 변수들 간의 상대적인 비교가 가능해진다."},{"n":3,"html":"데이터의 값들을 정규화하기 위해 (대상값-최댓값)/(최댓값-최솟값)의 수식을 이용한다."},{"n":4,"html":"데이터 스케일링은 변수들 각각의 범위나 분포를 동일하게 맞추는 데이터 전처리 작업 가운데 하나이다."}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8ac","number":8,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아파치 하둡(Apache Hadoop)의 작업을 관리하는 워크플로우 도구로 알맞은 것은 무엇인가?</p>","choices":[{"n":1,"html":"Hbase"},{"n":2,"html":"Pig"},{"n":3,"html":"Oozie"},{"n":4,"html":"Tajo"}],"answer":[3]},{"id":"6a67532a1bbde79cd2c1c89e","number":9,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>개인정보 처리자에게 금지되는 행위로 가장 옳지 않은 것은?</p>","choices":[{"n":1,"html":"개인정보의 분실, 도난, 유출, 위조, 변조 또는 훼손을 방지하기 위해 내부 관리 계획을 수립하고 데이터 익명화를 실시하는 행위"},{"n":2,"html":"업무 과정에서 알게 된 개인정보를 누설하거나 권한 없이 타인이 이용하도록 제공하는 행위"},{"n":3,"html":"부정한 수단이나 방법 또는 거짓으로 개인정보를 취득하거나 처리에 관한 동의를 받는 행위"},{"n":4,"html":"정당한 권한 없이 혹은 허용된 권한을 넘어서 다른 사람의 개인정보를 훼손, 멸실(파손), 변경, 위조 또는 유출하는 행위"}],"answer":[1]},{"id":"6a67532a1bbde79cd2c1c8a5","number":10,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 데이터를 수집할 때 고려해야 할 사항으로 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"데이터 수집의 용이성과 데이터 발생빈도, 그리고 데이터 전처리 및 후처리에 소요되는 비용 등을 고려한다."},{"n":2,"html":"적절한 데이터 분석모형을 활용하여 데이터 분석 주기를 고려한다."},{"n":3,"html":"데이터 분석 목표에 따라 데이터 도메인 정보, 이슈사항, 개선 사항 등을 반영한 데이터 품질 측정 계획을 수립한다."},{"n":4,"html":"데이터에 개인정보가 포함되어 있는지, 지적 재산권에 해당하는지를 고려해 적절한 조치 계획을 마련한다."}],"answer":[2]},{"id":"6a67532a1bbde79cd2c1c8a2","number":11,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석 시스템 구현 방법을 활용할 때, 빅데이터 분석절차를 올바른 순서로 나열한 것은?</p>","choices":[{"n":1,"html":"분석 기획 → 데이터 준비 → 시스템 구현 → 데이터 분석 → 평가 및 전개"},{"n":2,"html":"데이터 준비 → 분석 기획 → 데이터 분석 → 시스템 구현 → 평가 및 전개"},{"n":3,"html":"분석 기획 → 데이터 준비 → 데이터 분석 → 시스템 구현 → 평가 및 전개"},{"n":4,"html":"데이터 준비 → 분석 기획 → 시스템 구현 → 데이터 분석 → 평가 및 전개"}],"answer":[3]},{"id":"6a67532a1bbde79cd2c1c899","number":12,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 빅데이터의 대표적 특성으로 알려진 3V에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"Variation"},{"n":2,"html":"Variety"},{"n":3,"html":"Volume"},{"n":4,"html":"Velocity"}],"answer":[1]},{"id":"6a67532a1bbde79cd2c1c8a6","number":13,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래 보기에서 설명하고 있는 규제의 명칭으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>유럽 연합의 법률로, 유럽 연합 또는 유럽경제지역에 속한 모든 개인의 사생활과 개인정보를 보호하기 위한 규제이다. 유럽 연합 및 유럽경제지역 밖에서 발생한 개인정보 침해에 대해서도 적용될 수 있다. 이 규제는 개인정보의 자유로운 활용을 가능하게 하고, 유럽 내 보안 관련 제도를 통합하여 규제 성격이 강한 국제 비즈니스 환경을 단순화하는 것을 목표로 한다.</p></div>","choices":[{"n":1,"html":"Regulation EC"},{"n":2,"html":"Act EU"},{"n":3,"html":"Policy Directive"},{"n":4,"html":"GDPR"}],"answer":[4]},{"id":"6a67532a1bbde79cd2c1c8a0","number":14,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>한 기업이 다른 기업으로부터 별도의 인터페이스를 거쳐 데이터(개인정보 수집과 이용에 동의한 데이터)를 전달받고, 이를 기반으로 여러 서비스(금융기업 간 개인정보 공유, 고객의 신용·자산 통합 관리, 금융 상품 추천 등)를 제공하는 방식을 가리키는 용어는 무엇인가?</p>","choices":[{"n":1,"html":"개인정보 동의 간소화 서비스"},{"n":2,"html":"개인정보 보안 서비스"},{"n":3,"html":"개인정보 간소화 서비스"},{"n":4,"html":"마이 데이터 서비스"}],"answer":[4]},{"id":"6a67532a1bbde79cd2c1c8a3","number":15,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래 내용이 설명하는 빅데이터 분석 업무는 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>데이터 분석으로 개선사항을 도출하고자 분석 대상 과제의 현황을 파악</li><li>분석대상 과제의 문제점 파악을 위해 인터뷰, 설문조사 등을 실시</li><li>문제의 주요 이슈별 개선방향을 도출하여 개선과제를 정의하고 작성</li><li>문제를 인식하고 해결 목적을 명확하게 정의</li></ul></div>","choices":[{"n":1,"html":"도메인 이슈 도출"},{"n":2,"html":"빅데이터 시각화"},{"n":3,"html":"빅데이터 분석모형화"},{"n":4,"html":"빅데이터 분석 기획"}],"answer":[1]},{"id":"6a67532a1bbde79cd2c1c89f","number":16,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>재현 데이터(Synthetic Data)에 관한 설명 중 가장 적절한 것은 무엇인가?</p>","choices":[{"n":1,"html":"임의로 만들어진 것이 아니라 개인이 직접 제공하는 Real Data"},{"n":2,"html":"민감한 정보를 외부에 노출하지 않으면서도 모집단의 통계적 특성은 그대로 유지하도록 활용되는 데이터"},{"n":3,"html":"식별을 거친 뒤 실제 측정된 데이터와 완전히 동일하게 생성할 수 있는 데이터"},{"n":4,"html":"통계적 기법이나 머신러닝 학습 기법 등을 사용하지 않고 실제로 측정하여 얻은 데이터"}],"answer":[2]},{"id":"6a67532a1bbde79cd2c1c8a8","number":17,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래에서 설명하고 있는 데이터 품질관리 특성으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>실세계에 존재하는 객체(사건, 사물, 개념 등)의 값이 오류 없이 저장되어 있는 것을 의미함</li><li>분석대상에 대해 올바른 값이 저장됨</li><li>내재적(고유) 데이터 품질 특성(Intrinsic Data Quality)에 해당함</li><li>사실성, 적합성, 필수성, 연관성이라는 특징을 지님</li></ul></div>","choices":[{"n":1,"html":"적시성(Timeliness)"},{"n":2,"html":"정확성(Accuracy)"},{"n":3,"html":"일관성(Consistency)"},{"n":4,"html":"완전성(Completeness)"}],"answer":[2]},{"id":"6a67532b1bbde79cd2c1c8ab","number":18,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>조직의 의사결정 지원을 목적으로 널리 활용되는 데이터웨어하우스(Data Warehouse)의 주요 특징에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"시간의 흐름에 따라 변화하는 내용을 저장한다."},{"n":2,"html":"소멸성 자료의 집합을 저장한다."},{"n":3,"html":"통합된 내용을 저장한다."},{"n":4,"html":"주제 중심적인 특성을 가진다."}],"answer":[2]},{"id":"6a67532a1bbde79cd2c1c89c","number":19,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>전통적인 인공지능과 최신 인공지능을 비교한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"최신 인공지능의 가장 두드러진 특징은 명시적으로 지정된 작업을 절차에 따라 수행한다는 점이다."},{"n":2,"html":"최신 인공지능은 정해진 과업을 수행하기 위한 방법을 스스로 찾아내지 못한다."},{"n":3,"html":"전통적인 인공지능은 전문가가 미리 지정해둔 절차를 신뢰성 있게 수행한다."},{"n":4,"html":"전통적인 인공지능은 사람을 학습시키는 과정에서 아이디어를 얻은 방법을 활용한다."}],"answer":[3]},{"id":"6a67532a1bbde79cd2c1c8a4","number":20,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석을 목적으로 데이터 수집과 저장 계획을 세울 때 고려해야 할 사항으로 적절하지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"데이터 탐색 후 시각화 방법 및 계획 수립"},{"n":2,"html":"데이터 변환 방법과 그에 대한 계획 수립"},{"n":3,"html":"데이터의 유형과 속성 파악"},{"n":4,"html":"데이터의 수집·전환 및 적절성 검증에 대한 계획 수립"}],"answer":[1]},{"id":"6a67532b1bbde79cd2c1c8b5","number":21,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 그림과 같이 오른쪽으로 긴 꼬리를 갖는 분포 그래프에 대한 설명 중 옳은 것은?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 720 300\" width=\"720\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"왼쪽에 봉우리가 있고 오른쪽으로 긴 꼬리가 이어지는 단봉 분포 곡선과 가로축 및 세 위치 표시\">\n  <line x1=\"42\" y1=\"252\" x2=\"684\" y2=\"252\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  <path d=\"M62 251 C93 250 111 238 126 203 C145 157 162 83 196 51 C211 37 228 37 245 48 C275 67 297 108 327 145 C366 193 416 220 474 235 C534 247 597 250 670 251\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4.5\" stroke-linecap=\"round\"/>\n  <line x1=\"216\" y1=\"252\" x2=\"216\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-dasharray=\"3 7\"/>\n  <circle cx=\"216\" cy=\"40\" r=\"5\" fill=\"currentColor\"/>\n  <line x1=\"286\" y1=\"252\" x2=\"286\" y2=\"90\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-dasharray=\"3 7\"/>\n  <circle cx=\"286\" cy=\"90\" r=\"5\" fill=\"currentColor\"/>\n  <line x1=\"348\" y1=\"252\" x2=\"348\" y2=\"173\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-dasharray=\"3 7\"/>\n  <circle cx=\"348\" cy=\"173\" r=\"5\" fill=\"currentColor\"/>\n</svg></div>","choices":[{"n":1,"html":"왜도(Skewness) &gt; 0, 최빈값(Mode) &gt; 중앙값(Median) &gt; 평균값(Mean)"},{"n":2,"html":"왜도(Skewness) &lt; 0, 최빈값(Mode) &gt; 중앙값(Median) &gt; 평균값(Mean)"},{"n":3,"html":"왜도(Skewness) &lt; 0, 최빈값(Mode) &lt; 중앙값(Median) &lt; 평균값(Mean)"},{"n":4,"html":"왜도(Skewness) &gt; 0, 최빈값(Mode) &lt; 중앙값(Median) &lt; 평균값(Mean)"}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8c0","number":22,"category":"빅데이터 탐색","type":"choice","subject":"<p>유의확률(Significance Probability)에 관한 설명으로 옳은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"가설 검정에서 가설로부터 얻은 검정통계량이 특정 범위 내에 들어오면 해당 가정이 옳지 않다고 판단하게 되는데, 이때의 범위값"},{"n":2,"html":"대립가설이 참이라고 가정했을 때 주어진 검정통계량을 이용해 대립가설을 기각함으로써 발생하는 오류값"},{"n":3,"html":"모집단의 부분집합인 표본을 이용해 검정의 결론을 도출하고, 귀무가설의 기각 또는 채택 여부를 결정하는 데 사용되는 표본의 함수"},{"n":4,"html":"귀무가설이 참이라고 가정했을 때 주어진 검정통계량을 이용하여 구한 최소의 유의수준 값"}],"answer":[4]},{"id":"6a67532b1bbde79cd2c1c8b7","number":23,"category":"빅데이터 탐색","type":"choice","subject":"<p>탐색적 데이터 분석 단계에서 산출한 대푯값들에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"분산의 단위를 원래의 척도와 일치시키기 위해 분산에 제곱근을 취한 표준편차(Standard Deviation)를 사용한다."},{"n":2,"html":"분산(Variance)은 평균이 계산에 포함되므로 이상치에 민감하고, 원래 데이터의 속성값과는 단위가 다르다."},{"n":3,"html":"최빈치(Mode)는 이상치에 덜 민감하고, 데이터 분포가 비대칭일 때 평균보다 더 의미 있는 지표로 쓰인다."},{"n":4,"html":"중앙값(Median)은 이상치에 민감하고, 데이터 분포가 대칭일 때 평균보다 더 의미 있는 지표로 쓰인다."}],"answer":[4]},{"id":"6a67532b1bbde79cd2c1c8bc","number":24,"category":"빅데이터 탐색","type":"choice","subject":"<p><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math></span>개의 표본을 이용해 계산한 표본평균(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover></mrow></semantics></math></span>)의 정규분포 근사화에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"모평균이 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ</mi></mrow></semantics></math></span>이고 모분산이 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>σ</mi><mn>2</mn></msup></mrow></semantics></math></span>일 때, 임의로 추출한 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math></span>개의 표본에서 계산한 표본평균(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover></mrow></semantics></math></span>)의 분산은 모분산과 같다(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mi>a</mi><mi>r</mi><mo stretchy=\"false\">(</mo><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover><mo stretchy=\"false\">)</mo><mo lspace=\"0em\" rspace=\"0em\">=</mo><msup><mi>σ</mi><mn>2</mn></msup></mrow></semantics></math></span>)."},{"n":2,"html":"모집단이 정규분포를 따르지 않는 경우 표본평균(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover></mrow></semantics></math></span>)의 분포는 모집단의 분포에 따라 달라지지만, 표본의 크기(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math></span>)가 충분히 크면 모집단의 분포와 무관하게 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover></mrow></semantics></math></span>의 분포는 정규분포로 근사화된다."},{"n":3,"html":"평균이 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ</mi></mrow></semantics></math></span>이고 분산이 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>σ</mi><mn>2</mn></msup></mrow></semantics></math></span>인 정규모집단에서 임의로 추출한 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math></span>개의 표본으로 계산한 표본평균(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover></mrow></semantics></math></span>)의 표준편차는 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ</mi><mi mathvariant=\"normal\">/</mi><msqrt><mi>n</mi></msqrt><mtext> </mtext><mo stretchy=\"false\">(</mo><mi>s</mi><mi>d</mi><mo stretchy=\"false\">(</mo><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">)</mo><mo>=</mo><mi>σ</mi><mi mathvariant=\"normal\">/</mi><msqrt><mi>n</mi></msqrt></mrow></semantics></math></span>이다."},{"n":4,"html":"모평균이 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ</mi></mrow></semantics></math></span>이고 모분산이 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>σ</mi><mn>2</mn></msup></mrow></semantics></math></span>일 때, 임의로 추출한 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math></span>개의 표본에서 계산한 표본평균(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover></mrow></semantics></math></span>)의 평균은 모평균과 같다(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">(</mo><mover accent=\"true\"><mi>X</mi><mo stretchy=\"true\">‾</mo></mover><mo stretchy=\"false\">)</mo><mo lspace=\"0em\" rspace=\"0em\">=</mo><mi>μ</mi></mrow></semantics></math></span>)."}],"answer":[1]},{"id":"6a67532b1bbde79cd2c1c8b6","number":25,"category":"빅데이터 탐색","type":"choice","subject":"<p>기술 통계학에서 활용되는 통계량인 범위, 중앙값, 최빈값, 평균 가운데 나머지와 성질이 다른 하나는?</p>","choices":[{"n":1,"html":"최빈값(Mode)"},{"n":2,"html":"중앙값(Median)"},{"n":3,"html":"평균(Mean)"},{"n":4,"html":"범위(Range)"}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8bf","number":26,"category":"빅데이터 탐색","type":"choice","subject":"<p>유의수준(Significance Level)의 개념을 가장 올바르게 설명한 것은?</p>","choices":[{"n":1,"html":"유의수준이란 제2종 오류가 발생할 가능성을 뜻한다."},{"n":2,"html":"거짓인 귀무가설을 채택하게 되어 생기는 오류의 가능성을 설정해 놓은 값이다."},{"n":3,"html":"참인 귀무가설을 기각하게 되어 생기는 오류의 가능성을 설정해 놓은 값이다."},{"n":4,"html":"참인 대립가설을 기각하면서 발생하는 오류의 가능성을 설정해 놓은 값이다."}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8b1","number":27,"category":"빅데이터 탐색","type":"choice","subject":"<p>아래 그림을 활용해 주성분 분석 기반의 영상인식 시스템을 구축하려고 한다. 픽셀값으로부터 산출한 이미지의 특성값(공분산 행렬, <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi></mrow></semantics></math></span>)과 고유벡터(Eigenvector, <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi></mrow></semantics></math></span>)가 아래와 같이 주어졌을 때, 총분산의 값을 계산하시오. (단, 총분산은 고윳값(Eigen Value)의 합(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ</mi><mn>1</mn></msub><mo lspace=\"0em\" rspace=\"0em\">+</mo><msub><mi>λ</mi><mn>2</mn></msub></mrow></semantics></math></span>)으로 계산한다고 가정한다)</p><img class=\"q-img\" src=\"data:image/webp;base64,\" alt=\"고유얼굴(Eigenface) 몽타주 그림\"><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>공분산 행렬(2×2 matrix)&#160;&#160;<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mo>=</mo><mrow><mo fence=\"true\">[</mo><mtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0.5</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><mo>−</mo><mn>1</mn></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><mo>−</mo><mn>0.5</mn></mrow></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>1</mn></mstyle></mtd></mtr></mtable><mo fence=\"true\">]</mo></mrow></mrow></semantics></math></span></p><p>고윳값(2×2 matrix)&#160;&#160;<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Λ</mi><mo>=</mo><mrow><mo fence=\"true\">[</mo><mtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mi>λ</mi><mn>1</mn></msub></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0</mn></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mi>λ</mi><mn>2</mn></msub></mstyle></mtd></mtr></mtable><mo fence=\"true\">]</mo></mrow></mrow></semantics></math></span></p><p>고유벡터(2×1 matrix)&#160;&#160;<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi><mo>=</mo><mrow><mo fence=\"true\">[</mo><mtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0.6</mn></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0.4</mn></mstyle></mtd></mtr></mtable><mo fence=\"true\">]</mo></mrow></mrow></semantics></math></span></p></div>","choices":[{"n":1,"html":"0.07"},{"n":2,"html":"0.08"},{"n":3,"html":"1.07"},{"n":4,"html":"1.08"}],"answer":[2]},{"id":"6a67532b1bbde79cd2c1c8bb","number":28,"category":"빅데이터 탐색","type":"choice","subject":"<p>서로 독립인(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>o</mi><mi>v</mi><mo stretchy=\"false\">(</mo><mi>X</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>Y</mi><mo stretchy=\"false\">)</mo><mo lspace=\"0em\" rspace=\"0em\">=</mo><mn>0</mn></mrow></semantics></math></span>) 두 확률변수 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi></mrow></semantics></math></span>와 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y</mi></mrow></semantics></math></span>가 포아송분포를 따르고, 평균은 각각 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">(</mo><mi>X</mi><mo stretchy=\"false\">)</mo><mo lspace=\"0em\" rspace=\"0em\">=</mo><mn>4</mn></mrow></semantics></math></span>, <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">(</mo><mi>Y</mi><mo stretchy=\"false\">)</mo><mo lspace=\"0em\" rspace=\"0em\">=</mo><mn>9</mn></mrow></semantics></math></span>라고 한다. 이때 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mi>E</mi><mo stretchy=\"false\">(</mo><mo stretchy=\"false\">(</mo><mn>3</mn><mi>X</mi><mo lspace=\"0em\" rspace=\"0em\">+</mo><mn>2</mn><mi>Y</mi><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mn>6</mn><mo stretchy=\"false\">)</mo></mrow></semantics></math></span>, <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mi>V</mi><mi>a</mi><mi>r</mi><mo stretchy=\"false\">(</mo><mo stretchy=\"false\">(</mo><mn>3</mn><mi>X</mi><mo lspace=\"0em\" rspace=\"0em\">+</mo><mn>2</mn><mi>Y</mi><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mn>6</mn><mo stretchy=\"false\">)</mo></mrow></semantics></math></span>이라 하면 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi></mrow></semantics></math></span>와 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi></mrow></semantics></math></span>는 각각 얼마인가?</p>","choices":[{"n":1,"html":"a=2, b=5"},{"n":2,"html":"a=5, b=2"},{"n":3,"html":"a=3, b=6"},{"n":4,"html":"a=6, b=3"}],"answer":[2]},{"id":"6a67532b1bbde79cd2c1c8ad","number":29,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터 정제 단계에서 이루어져야 하는 작업으로 알맞은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"변수를 그 기능에 따라 독립, 종속, 통제, 매개, 왜생, 억압 변수로 나눈다."},{"n":2,"html":"대량의 빅데이터를 분석하기 위해, 분석 대상인 여러 변수들의 핵심 정보를 최대한 보존하면서 데이터세트의 변수 개수를 축소한다."},{"n":3,"html":"결측치, 잡음, 이상치와 같이 데이터 오류를 유발하는 주요 요소들을 제거한다."},{"n":4,"html":"데이터가 지닌 변수의 내재 변동성 유형을 확인하고, 변수들 사이의 공통변동이 무엇인지 살펴본다."}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8b0","number":30,"category":"빅데이터 탐색","type":"choice","subject":"<p>주성분 분석(PCA, Principal Component Analysis)은 차원축소에 활용되는 기법이다. 이때 사용되는 공분산 행렬에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"고유벡터는 공분산 행렬을 이용해 구하는데, 고유벡터란 행렬의 방향성을 유지하는 선형변환의 주축을 뜻(선형변환 후 크기만 변하고 방향은 그대로)한다."},{"n":2,"html":"중요한 주성분들은 공분산 행렬의 고유벡터에 해당하므로 서로 직교한다."},{"n":3,"html":"변수들의 공분산 행렬을 활용해 기본 변수들을 분산이 작은 변수들로 변환하면 유의성이 높은 변수들로 데이터를 나타낼 수 있게 된다."},{"n":4,"html":"공분산 행렬의 고유벡터가 해당 데이터를 대표하는 주축이 되도록 만드는 방식으로 주성분을 판별한다."}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8b9","number":31,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 데이터 분석 시 표본조사 방법 대신 전수조사를 실시해야 하는 경우로 가장 적절한 것은?</p>","choices":[{"n":1,"html":"남해안의 고래 수"},{"n":2,"html":"암환자 중 5년 생존자 수"},{"n":3,"html":"우주선 부품 조사"},{"n":4,"html":"선거에서 후보자 지지율 조사"}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8af","number":32,"category":"빅데이터 탐색","type":"choice","subject":"<p>주성분 분석(PCA, Principal Component Analysis)에 관한 다음 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"변수 간에 상관관계가 존재하는 다차원의 데이터를 분석에 필요한 차원축소 과정을 거쳐 저차원의 데이터로 표현한다."},{"n":2,"html":"통계적으로 독립변수들 사이에 상관관계가 없도록 만들고 요인 적재값을 확인하며, 요인 적재값에 차이가 없어 요인 분류가 어려울 때는 데이터 회전 방법으로 분석을 수행한다."},{"n":3,"html":"비음수 행렬분해 분석방법으로서, 음수가 포함되지 않은 전체 원소가 양수인 행렬 V를 음수를 포함하지 않는 행렬 W와 H의 곱으로 분해하는 알고리즘이다."},{"n":4,"html":"고윳값과 고유벡터를 계산한 뒤, 고유벡터를 열벡터로 갖는 행렬의 대각화를 통해 고윳값을 분해하고, 가장 큰 고윳값을 중심으로 기존 변수들을 선형결합하여 얻은 새로운 변수들로 변환한다."}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8bd","number":33,"category":"빅데이터 탐색","type":"choice","subject":"<p>중심극한정리(Central Limit Theorem)에 관한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"모집단이 이산형 분포일 때는 표본의 크기가 크더라도 표본평균이 정규분포를 따르지 않는다."},{"n":2,"html":"모집단의 분포가 정규분포라 하더라도 표본의 크기가 크면 표본평균은 정규분포를 따르지 않는다."},{"n":3,"html":"분포의 비대칭 정도를 나타내는 왜도(Skewness)가 양수 또는 음수인 경우라도 표본의 크기가 크면 표본평균은 정규분포를 따른다."},{"n":4,"html":"표본의 크기가 크다면 여러 모집단에서 추출한 표본평균 역시 정규분포를 따른다."}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8ae","number":34,"category":"빅데이터 탐색","type":"choice","subject":"<p>변수 처리 과정에서 활용되는 차원축소(Dimensionality Reduction)에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"차원축소에 대표적으로 활용되는 요인분석(Factor Analysis)은 설정된 분석모형을 바탕으로 주요 변수와 유사한 특징을 지닌 변수를 제거하는 방법이다."},{"n":2,"html":"차원축소는 대규모 빅데이터를 분석할 때, 분석대상인 여러 변수들의 핵심 정보를 최대한 보존하면서 데이터세트에 포함된 변수의 수를 줄여나가는 일련의 탐색적 분석 기법을 말한다."},{"n":3,"html":"차원축소에 대표적으로 활용되는 다차원 척도법(Multi-Dimensional Scaling)은 고차원 데이터를 해석하기 쉽도록 가시적인 저차원 공간으로 사상하여 나타낸다."},{"n":4,"html":"차원축소 기법은 주로 다른 분석 과정에 앞선 사전 단계에서 활용되고, 분석을 수행한 뒤에는 결괏값을 활용한 효과적인 시각화 등에도 사용된다."}],"answer":[1]},{"id":"6a67532b1bbde79cd2c1c8b2","number":35,"category":"빅데이터 탐색","type":"choice","subject":"<p>박스칵스 변환(Box-cox Transformation)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"거듭곱 변환과 로그 변환이 포함된다."},{"n":2,"html":"데이터 분석을 효율적으로 수행하기 위해 사용하는 변수 변환 방법들 중 하나이다."},{"n":3,"html":"정규성을 가정하는 분석 방법이나 정상성(분산을 안정화)을 요구하는 분석 방법을 적용하기에 앞서 사용된다."},{"n":4,"html":"파생변수를 생성하는 방법 가운데 하나이다."}],"answer":[4]},{"id":"6a67532b1bbde79cd2c1c8be","number":36,"category":"빅데이터 탐색","type":"choice","subject":"<p>점추정(Point Estimation)에 사용되는 추정량이 갖추어야 할 주요 성질(추정량 결정기준)에 해당하지 않는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"일치성(Consistency)"},{"n":2,"html":"편의성(Convenience)"},{"n":3,"html":"효율성(Efficiency)"},{"n":4,"html":"충분성(Sufficiency)"}],"answer":[2]},{"id":"6a67532b1bbde79cd2c1c8b8","number":37,"category":"빅데이터 탐색","type":"choice","subject":"<p>기술통계에서 대표값으로 흔히 쓰이는 평균(Mean)에 관한 설명 중 옳은 것은?</p>","choices":[{"n":1,"html":"평균의 단위는 평균을 구하기 위해 수집한 데이터 관측값의 단위와 동일하다."},{"n":2,"html":"평균은 일반적으로 데이터를 크기순으로 나열했을 때 가운데에 위치하는 값과 같다."},{"n":3,"html":"평균은 이상치의 영향을 전혀 받지 않는 값이다."},{"n":4,"html":"데이터가 대칭적으로 분포된 경우 평균은 옳지 않은 정보를 제공한다."}],"answer":[1]},{"id":"6a67532b1bbde79cd2c1c8ba","number":38,"category":"빅데이터 탐색","type":"choice","subject":"<p>확률적 근거에 기반하여 표본을 뽑는 확률표본추출방법 가운데, 집단 내부는 이질적이고 집단 사이는 동질적인 특성을 보이는 방법은 무엇인가?</p>","choices":[{"n":1,"html":"계통추출"},{"n":2,"html":"군집(집락표본)추출"},{"n":3,"html":"단순임의추출"},{"n":4,"html":"층화추출"}],"answer":[2]},{"id":"6a67532b1bbde79cd2c1c8b4","number":39,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 상관계수의 기본 개념에 대한 설명으로 올바른 것은?</p>","choices":[{"n":1,"html":"상관계수 값이 0인 경우 양의 상관관계를 가진다고 한다."},{"n":2,"html":"두 변수 사이의 비선형 정도는 상관계수 값을 통해 파악한다."},{"n":3,"html":"상관계수 값이 -1인 경우 음의 상관관계를 가진다고 한다."},{"n":4,"html":"상관계수 값이 1인 경우 상관관계가 없다고 한다."}],"answer":[3]},{"id":"6a67532b1bbde79cd2c1c8b3","number":40,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 불균형 데이터(Imbalanced Data)에 관한 설명 중 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"데이터 타깃의 수가 매우 극소수인 비대칭 데이터세트를 활용할 경우 분류 및 예측 모델의 정확도, 민감도, 재현율이 높게 나타난다."},{"n":2,"html":"소수 클래스 데이터를 늘리는 오버 샘플링 방법은 기준을 정해 무작위로 소수 데이터를 복제하는 방식으로, 정보가 손실되지 않는 장점이 있지만 여러 유형의 관측치를 다수 추가하여 Overfitting을 유발할 수 있다."},{"n":3,"html":"데이터 불균형은 어떤 데이터에서 각 클래스(주로 범주형 변수)별로 보유한 데이터 양의 차이가 큰 경우를 뜻한다."},{"n":4,"html":"다수 클래스 데이터 중 일부만 사용하는 다운(또는 언더) 샘플링 방법은 유의한 데이터만 남기는 방식을 사용하는데, 데이터 손실이 크고 경우에 따라 정상 데이터를 잃기도 한다."}],"answer":[1]},{"id":"6a67532c1bbde79cd2c1c8c4","number":41,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 그림에 제시된 인공신경망에서 활성화 함수가 출력하는 결과 가운데 <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Y</mi><mn>3</mn></msub></mrow></semantics></math></span>의 값은 얼마인가? [단, Output <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mo stretchy=\"false\">(</mo><msub><mi>Y</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Y</mi><mn>2</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Y</mi><mn>3</mn></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math></span>의 값은 Input <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mo stretchy=\"false\">(</mo><msub><mi>X</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>X</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math></span>과 Weight <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mo stretchy=\"false\">(</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo separator=\"true\">,</mo><mn>2</mn><mo separator=\"true\">,</mo><mn>7</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mo stretchy=\"false\">(</mo><mn>4</mn><mo separator=\"true\">,</mo><mn>5</mn><mo separator=\"true\">,</mo><mn>6</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">)</mo></mrow></semantics></math></span>의 행렬 곱을 통해 계산된다]</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 760 560\" width=\"760\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"입력값 1과 2를 갖는 입력 노드 X₁, X₂와 출력 노드 Y₁, Y₂, Y₃ 사이의 여섯 가중치 및 행렬곱 관계\">\n  <defs>\n    <marker id=\"weight-arrow\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\">\n      <path d=\"M0 0 L10 5 L0 10 Z\" fill=\"currentColor\"/>\n    </marker>\n  </defs>\n\n  <text x=\"380\" y=\"28\" font-size=\"20\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">Input X</text>\n\n  <rect x=\"157\" y=\"48\" width=\"106\" height=\"88\" rx=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  <text x=\"210\" y=\"82\" font-size=\"21\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">X₁</text>\n  <line x1=\"171\" y1=\"94\" x2=\"249\" y2=\"94\" stroke=\"currentColor\" stroke-width=\"1\"/>\n  <text x=\"210\" y=\"119\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">입력값 1</text>\n\n  <rect x=\"497\" y=\"48\" width=\"106\" height=\"88\" rx=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  <text x=\"550\" y=\"82\" font-size=\"21\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">X₂</text>\n  <line x1=\"511\" y1=\"94\" x2=\"589\" y2=\"94\" stroke=\"currentColor\" stroke-width=\"1\"/>\n  <text x=\"550\" y=\"119\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">입력값 2</text>\n\n  <rect x=\"45\" y=\"158\" width=\"670\" height=\"184\" rx=\"24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"7 6\"/>\n  <text x=\"25\" y=\"250\" font-size=\"18\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\" transform=\"rotate(-90 25 250)\">Weight W</text>\n\n  <path d=\"M178 132 C145 190 129 270 129 382\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#weight-arrow)\"/>\n  <path d=\"M205 136 C205 218 276 293 356 390\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#weight-arrow)\"/>\n  <path d=\"M236 132 C310 202 504 247 613 389\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#weight-arrow)\"/>\n\n  <path d=\"M524 132 C450 202 256 247 147 389\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#weight-arrow)\"/>\n  <path d=\"M555 136 C555 218 484 293 404 390\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#weight-arrow)\"/>\n  <path d=\"M582 132 C615 190 631 270 631 382\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" marker-end=\"url(#weight-arrow)\"/>\n\n  <text x=\"104\" y=\"210\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\">X₁→Y₁</text>\n  <text x=\"104\" y=\"232\" font-size=\"19\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">1</text>\n\n  <text x=\"218\" y=\"190\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\">X₁→Y₂</text>\n  <text x=\"218\" y=\"212\" font-size=\"19\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">2</text>\n\n  <text x=\"302\" y=\"170\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\">X₁→Y₃</text>\n  <text x=\"302\" y=\"192\" font-size=\"19\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">7</text>\n\n  <text x=\"458\" y=\"170\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\">X₂→Y₁</text>\n  <text x=\"458\" y=\"192\" font-size=\"19\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">4</text>\n\n  <text x=\"542\" y=\"190\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\">X₂→Y₂</text>\n  <text x=\"542\" y=\"212\" font-size=\"19\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">5</text>\n\n  <text x=\"656\" y=\"210\" font-size=\"12\" fill=\"currentColor\" text-anchor=\"middle\">X₂→Y₃</text>\n  <text x=\"656\" y=\"232\" font-size=\"19\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">6</text>\n\n  <text x=\"380\" y=\"366\" font-size=\"20\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">Output Y</text>\n\n  <circle cx=\"130\" cy=\"425\" r=\"39\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  <text x=\"130\" y=\"432\" font-size=\"21\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">Y₁</text>\n\n  <circle cx=\"380\" cy=\"425\" r=\"39\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  <text x=\"380\" y=\"432\" font-size=\"21\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">Y₂</text>\n\n  <circle cx=\"630\" cy=\"425\" r=\"39\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  <text x=\"630\" y=\"432\" font-size=\"21\" font-weight=\"700\" fill=\"currentColor\" text-anchor=\"middle\">Y₃</text>\n\n  <line x1=\"100\" y1=\"483\" x2=\"660\" y2=\"483\" stroke=\"currentColor\" stroke-width=\"1\"/>\n\n  <text x=\"380\" y=\"516\" font-size=\"19\" fill=\"currentColor\" text-anchor=\"middle\">X  *  W  =  Y</text>\n  <text x=\"380\" y=\"544\" font-size=\"17\" fill=\"currentColor\" text-anchor=\"middle\">1×2  *  2×3  =  1×3</text>\n</svg></div>","choices":[{"n":1,"html":"7"},{"n":2,"html":"12"},{"n":3,"html":"13"},{"n":4,"html":"19"}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8d4","number":42,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 자료는 5명의 의사가 네 가지 혈압 치료약(A, B, C, D)에 대해 매긴 선호도 서열을 정리한 것이다. 이 자료를 Friedman(프리드만) 검정으로 분석한 결과, 카이제곱 검정통계량=6.36, 자유도=3, (근사)유의확률=0.095을 얻었다. 다음 중 이 결과에 대한 해석으로 적절하지 않은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>의사</th><th>치료약 A</th><th>치료약 B</th><th>치료약 C</th><th>치료약 D</th></tr><tr><td>1</td><td>1</td><td>2</td><td>4</td><td>3</td></tr><tr><td>2</td><td>2</td><td>1</td><td>3</td><td>4</td></tr><tr><td>3</td><td>1</td><td>3</td><td>4</td><td>2</td></tr><tr><td>4</td><td>1</td><td>3</td><td>2</td><td>4</td></tr><tr><td>5</td><td>2</td><td>3</td><td>4</td><td>1</td></tr><tr><td>평균 순위</td><td>1.4</td><td>2.4</td><td>3.4</td><td>2.8</td></tr></table></div>","choices":[{"n":1,"html":"프리드만 검정을 수행하기 위해 대립가설은 &quot;4개 혈압 치료약에 대한 의사들의 평균 선호도(순위)에 차이가 있다&quot;로 세운다."},{"n":2,"html":"프리드만 검정은 순위의 합을 산출하여 변수들 사이의 평균 순위에 차이가 존재하는지를 검정하는 방법이다."},{"n":3,"html":"유의수준 5%에서 귀무가설을 기각할 수 없으므로, 4가지 혈압 치료약에 대한 의사들의 선호도에 차이가 있다고 결론 내릴 수 있다."},{"n":4,"html":"카이제곱 검정통계량으로부터 구한 유의확률 값(0.095)이 유의수준(0.05)을 초과하므로 귀무가설을 기각할 수 없다."}],"answer":[3]},{"id":"6a67532c1bbde79cd2c1c8c1","number":43,"category":"빅데이터 모델링","type":"choice","subject":"<p>회귀분석을 할 때 독립변수들 간의 강한 상관관계 때문에 나타나는 다중공선성(Multicollinearity) 문제에 대한 해결 방법으로 적절하지 않은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"박스칵스(Box-cox) 변환 기법을 활용하여 해결한다."},{"n":2,"html":"변수를 변형하거나 새로운 관측치를 활용한다."},{"n":3,"html":"릿지(Ridge) 함수를 활용해 모형의 가중치를 제한하고 다항식의 차수를 줄인다."},{"n":4,"html":"다중공선성을 유발하는 독립(설명) 변수들 가운데 하나 또는 일부를 제거한다."}],"answer":[1]},{"id":"6a67532c1bbde79cd2c1c8cb","number":44,"category":"빅데이터 모델링","type":"choice","subject":"<p>딥러닝 기법 중 하나인 심층신뢰신경망(DBN, Deep Belief Network)에 관한 설명 가운데 옳은 것은?</p>","choices":[{"n":1,"html":"데이터 학습을 위해 레이블이 부여된 데이터를 활용하는 지도 학습 방법을 이용한다."},{"n":2,"html":"입력된 데이터의 가중합을 출력 신호로 변환하는 데 주로 비선형 활성화 함수를 사용한다."},{"n":3,"html":"충분한 학습 데이터가 필요하며, 제한된 Gradient Descent Vanishing 문제가 여전히 해결되지 않는 구조를 제공한다."},{"n":4,"html":"입력 집합에 대한 확률 분포를 학습하는 신경망 구조인 RBM(Restricted Boltzmann Machine)을 전혀 사용하지 않는다."}],"answer":[2]},{"id":"6a67532c1bbde79cd2c1c8d0","number":45,"category":"빅데이터 모델링","type":"choice","subject":"<p>사회연결망 분석(Social Network Analysis)에서 노드의 중심성(Centrality)을 평가하는 척도에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"밀도(Density)는 네트워크 안에서 가능한 최대 관계 수 대비 실제로 형성된 관계 수의 비율로 계산한다."},{"n":2,"html":"연결정도(Degree)는 노드 사이의 총 연결관계 개수를 뜻하며, 특정 노드가 몇 개의 노드와 연결되어 있는지를 보여준다."},{"n":3,"html":"중요한 노드와 많이 연결되어 있는 노드를 더 중요하게 평가하기 위해 고윳값을 계산하고 그중 가장 큰 고윳값에 대응하는 아이겐벡터를 구하는 방식을 관계 중심성 평가라고 한다."},{"n":4,"html":"하나의 노드에 연결된 전체 Edge 개수로 중심성을 측정하며, 연결된 Edge 수가 가장 많은 노드를 중심성이 높다고 판단하는 방식을 연결 중심성 평가라고 한다."}],"answer":[3]},{"id":"6a67532c1bbde79cd2c1c8c8","number":46,"category":"빅데이터 모델링","type":"choice","subject":"<p>시계열 자료에서 서로 다른 시차 값(Lagged Value) 간의 선형관계를 파악하는 데 활용되는 것은 무엇인가?</p>","choices":[{"n":1,"html":"자기상관(Autocorrelation)"},{"n":2,"html":"데이터 편중(Data Bias)"},{"n":3,"html":"데이터 차분(Data Differencing)"},{"n":4,"html":"백색잡음(White Noise)"}],"answer":[1]},{"id":"6a67532c1bbde79cd2c1c8c3","number":47,"category":"빅데이터 모델링","type":"choice","subject":"<p>목표변수가 이산형일 때 의사결정나무 분석모형을 적용하는 경우, 활용되는 검정 방법에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"엔트로피 지수 이용"},{"n":2,"html":"F-통계량 이용(F-검정)"},{"n":3,"html":"지니지수 이용"},{"n":4,"html":"카이제곱 통계량 이용(카이제곱 검정)"}],"answer":[2]},{"id":"6a67532c1bbde79cd2c1c8c6","number":48,"category":"빅데이터 모델링","type":"choice","subject":"<p>커널 함수(Kernel Function)에 관한 다음 설명 가운데 옳지 않은 것은?</p>","choices":[{"n":1,"html":"비모수적 추정에서 커널 밀도 추정을 수행할 때 커널 함수를 사용하며, 이때 관측된 각 데이터 값을 중심으로 커널 함수를 반복적으로 생성하는 방식을 취한다."},{"n":2,"html":"SVM 분류에서 저차원 공간에서는 선형 분리가 불가능한 데이터를 고차원 공간으로 매핑하여 선형분리가 가능하도록 만들 때, 매핑함수의 내적으로 커널 함수가 활용된다."},{"n":3,"html":"커널 함수는 수학적으로 원점에 대해 대칭이고 적분값이 1인 Non-negative 함수로 정의된다."},{"n":4,"html":"홀드아웃, 다중교차와 같은 교차검증 기법에서 훈련용 데이터세트를 분류하는 데 주로 활용된다."}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8cf","number":49,"category":"빅데이터 모델링","type":"choice","subject":"<p>심층신경망을 이용한 딥러닝 분석에서 비용함수 최소화를 위해 활용하는 경사하강법(Gradient Descent) 기법에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"RMSProp"},{"n":2,"html":"AdaBoost"},{"n":3,"html":"Nesterov Accelerated Gradient"},{"n":4,"html":"Adam"}],"answer":[2]},{"id":"6a67532c1bbde79cd2c1c8d2","number":50,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 상황에서 사용하기에 알맞은 비모수 검정 방법은 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>우리나라 대학생의 IQ 중앙값은 115이다.</li><li>K대학 학생들의 IQ 중앙값이 115 이상이라는 주장이 제기되었다.</li><li>이 주장의 타당성을 검토하기 위해 K대학 학생 20명을 무작위로 뽑아 IQ를 측정하였다.</li><li>유의수준 α=0.05에서 비모수 검정 방법으로 검정하려고 한다.</li></ul></div>","choices":[{"n":1,"html":"런 검정(Run Test)"},{"n":2,"html":"대응표본 t-검정(Paired T-test)"},{"n":3,"html":"부호 검정(Sign Test)"},{"n":4,"html":"Kolmogorov-Smirnov 검정"}],"answer":[3]},{"id":"6a67532c1bbde79cd2c1c8d1","number":51,"category":"빅데이터 모델링","type":"choice","subject":"<p>분류의 정확도를 향상시키기 위해 여러 분류 모형의 결과를 결합하는 앙상블 분석(Ensemble Analysis)이 활용된다. 앙상블 분석모형의 설계에 사용되는 학습법 가운데, 가중치를 활용해 약 분류기를 강 분류기로 발전시키는 기법은 무엇인가?</p>","choices":[{"n":1,"html":"Bootstrap Aggregation"},{"n":2,"html":"Bagging"},{"n":3,"html":"Random Forest"},{"n":4,"html":"Boosting"}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8c2","number":52,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음은 단순회귀분석 결과에서 모형의 유의성을 검정하고자 만든 분산분석표(ANOVA, Analysis of Variance)이다. 아래 설명 가운데 옳지 않은 것은 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl is-center\"><tr><th>요 인</th><th>제곱합</th><th>자유도</th><th>제곱평균</th><th><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow></semantics></math></span></th></tr><tr><th>회 귀</th><td>SSR</td><td><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn></mrow></semantics></math></span></td><td><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi><mi>S</mi><mi>R</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mfrac><mrow><mi>S</mi><mi>S</mi><mi>R</mi></mrow><mn>1</mn></mfrac></mrow></semantics></math></span></td><td rowspan=\"2\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mfrac><mrow><mi>M</mi><mi>S</mi><mi>R</mi></mrow><mrow><mi>M</mi><mi>S</mi><mi>E</mi></mrow></mfrac></mrow></semantics></math></span></td></tr><tr><th>잔 차</th><td>SSE</td><td><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>−</mo><mn>2</mn></mrow></semantics></math></span></td><td><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi><mi>S</mi><mi>E</mi><mo lspace=\"0em\" rspace=\"0em\">=</mo><mfrac><mrow><mi>S</mi><mi>S</mi><mi>E</mi></mrow><mrow><mi>n</mi><mo>−</mo><mn>2</mn></mrow></mfrac></mrow></semantics></math></span></td></tr><tr><th>전 체</th><td>SST</td><td><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></semantics></math></span></td><td>-</td><td></td></tr></table></div>","choices":[{"n":1,"html":"ANOVA 표를 활용하면 종속변수의 표본분산을 계산할 수 있다."},{"n":2,"html":"독립변수와 종속변수의 선형성, 오차의 정규성, 등분산성, 독립성은 ANOVA 표를 통해 검정이 가능하다."},{"n":3,"html":"F통계량 값으로부터 유의확률을 산출하고, 그 유의확률이 유의수준(α)보다 작으면 회귀식이 유의하다고 판단한다."},{"n":4,"html":"회귀 요인의 제곱합은 종속변수를 회귀식으로 추정할 때 설명되는 분산을 의미하며, 잔차의 제곱합은 회귀식으로 설명되지 않는 분산에 해당한다."}],"answer":[2]},{"id":"6a67532c1bbde79cd2c1c8c9","number":53,"category":"빅데이터 모델링","type":"choice","subject":"<p>시계열 데이터 분석에 활용되는 자기회귀 누적이동평균모형(ARIMA, Autoregressive Integrated Moving Average)에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"ARIMA(p, d, q)에서 d는 ARMA 모형으로 정상화(자료 변동이 시간에 따라 일정)하기 위해 몇 번 차분했는지를 나타낸다."},{"n":2,"html":"ARIMA(p, d, q)에서 p는 AR(Autoregressive) 모형과 관련이 있고 q는 MA(Moving Average) 모형과 관련이 있다."},{"n":3,"html":"ARIMA(p, d, q)에서 p는 자기회귀부분의 차수를, d는 1차 차분이 포함된 정도를, q는 이동평균 부분의 차수를 나타낸다."},{"n":4,"html":"ARIMA(p, d, q)에서 d=0이 되면 정상성을 만족하지 못하게 되어 ARMA(p, q) 모형을 적용할 수 없다."}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8d3","number":54,"category":"빅데이터 모델링","type":"choice","subject":"<p>모집단에 대해 정규분포를 가정하기 어려운 상황에서, 짝을 이룬 표본(대응표본)에 대한 비모수 검정 방법으로 가장 적절한 것은 무엇인가?</p>","choices":[{"n":1,"html":"런 검정(Run Test)"},{"n":2,"html":"윌콕슨 부호순위 검정(Wilcoxon Signed Rank Test)"},{"n":3,"html":"부호 검정(Sign Test)"},{"n":4,"html":"대응표본 t-검정(Paired T-test)"}],"answer":[2]},{"id":"6a67532c1bbde79cd2c1c8c5","number":55,"category":"빅데이터 모델링","type":"choice","subject":"<p>인공신경망 모델에서 학습으로 결정되지 않고 사용자가 미리 직접 설정해야 하는 하이퍼파라미터는 무엇인가?</p>","choices":[{"n":1,"html":"목표변수 결괏값(Target Values)"},{"n":2,"html":"학습률(Learning Rate)"},{"n":3,"html":"가중치(Weights)"},{"n":4,"html":"편향(Bias)"}],"answer":[2]},{"id":"6a67532c1bbde79cd2c1c8c7","number":56,"category":"빅데이터 모델링","type":"choice","subject":"<p>서포트벡터머신(SVM, Support Vector Machine)은 서로 다른 분류에 속한 데이터 간의 간격(Margin)을 최대로 하는 평면을 찾고 이를 기준으로 분류 결과를 도출하는 기법이다. 이 중 RBF(Radial Basis Function) 커널 트릭 기법에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"가우시안 RBF 커널 기법은 비용과 감마라는 두 가지 매개변수를 사용하며, 매개변수 값이 증가할수록 알고리즘의 복잡도도 증가한다."},{"n":2,"html":"가우시안 RBF 커널 기법은 비용과 감마라는 두 가지 매개변수를 사용하며, 경험적 방법인 Grid Search 알고리즘을 통해 적정한 매개변수 값을 찾는다."},{"n":3,"html":"비용과 감마라는 두 가지 매개변수를 사용하는 가우시안 RBF 커널 기법에서, 비용 매개변수는 데이터 샘플이 다른 클래스에 놓이는 것을 허용하는 정도를 정하며, 감마는 결정 경계의 곡률을 정한다."},{"n":4,"html":"가우시안 RBF 커널 기법은 비용과 감마라는 두 가지 매개변수를 사용하며, 비용 매개변수 값이 증가할수록, 감마 매개변수 값이 감소할수록 과대적합(Overfitting)의 위험이 있다."}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8cc","number":57,"category":"빅데이터 모델링","type":"choice","subject":"<p>딥러닝에서 활용하는 소프트맥스(Softmax) 활성화 함수에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"각 클래스에 대한 예측 결과를 정규화해 확률값으로 나타내며, 확률의 총합은 1이 된다."},{"n":2,"html":"세 개 이상의 클래스로 나누는 다중 클래스 분류에서 Softmax 함수가 주로 사용된다."},{"n":3,"html":"입력값들 간 차이가 작으면 출력값들이 잘 구별되지 않으며, 출력값들의 분산은 1이다."},{"n":4,"html":"분류할 클래스가 n개인 경우, n차원의 벡터를 입력으로 받아 각 클래스에 속할 확률을 추정한다."}],"answer":[3]},{"id":"6a67532c1bbde79cd2c1c8ce","number":58,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 설명에 부합하는 인공신경망의 활성화 함수는 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>유한한 구간 (a, b) 내의 한정된 값을 반환하며, a와 b로는 주로 0과 1이 사용된다.</li><li>정의역은 실수 전체 집합이고 S자 곡선 형태를 갖는다.</li><li>정의역의 절댓값이 커질수록 미분값=0으로 수렴한다.</li><li>가중치가 업데이트되지 않고 소실되는 기울기 손실 현상이 나타날 수 있다.</li></ul></div>","choices":[{"n":1,"html":"ELU(Exponential Linear Unit)"},{"n":2,"html":"시그모이드(Sigmoid)"},{"n":3,"html":"하이퍼볼릭 탄젠트(Hyperbolic Tangent)"},{"n":4,"html":"ReLU(Rectified Linear Unit)"}],"answer":[2]},{"id":"6a67532c1bbde79cd2c1c8ca","number":59,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 설명과 해당 기법의 연결이 올바른 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>(가)</th><td><ul><li>합성곱 연산을 사용</li><li>Feature Map을 활용하여 학습</li><li>로봇 이미지 인식, 컴퓨터 비전, 영상분석 및 인식</li></ul></td></tr><tr><th>(나)</th><td><ul><li>노드 사이의 연결이 순환 구조를 이룸</li><li>주가예측과 같은 순차적 데이터 처리 분야에서 활용</li><li>필기체 텍스트, 음성, 언어 번역</li></ul></td></tr><tr><th>(다)</th><td><ul><li>제로섬 게임의 틀 안에서 서로 경쟁하는 신경망을 활용</li><li>가짜를 생성하는 모델과 진위 여부를 판별하는 모델 간의 경쟁</li><li>컴퓨터 게임, 패션, 광고</li></ul></td></tr><tr><th>(라)</th><td><ul><li>행동심리학에서 영감을 얻음</li><li>마코프 프로세스 결정 모델을 활용</li><li>게임, 제어, 정보 이론, 다중 에이전트 시스템</li></ul></td></tr></table></div>","choices":[{"n":1,"html":"(가) CNN, (라) 강화 학습"},{"n":2,"html":"(나) RNN, (다) 강화 학습"},{"n":3,"html":"(나) RNN, (다) DBN"},{"n":4,"html":"(가) CNN, (라) Markov Decision Process"}],"answer":[1]},{"id":"6a67532c1bbde79cd2c1c8cd","number":60,"category":"빅데이터 모델링","type":"choice","subject":"<p>인공신경망의 활성화 함수(Activation Function)에 관한 설명 중 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"시그모이드 활성화 함수의 정의역은 정수로만 제한된다."},{"n":2,"html":"은닉층 수가 늘어나면 매개변수도 함께 증가하여 요구되는 연산량이 많아진다."},{"n":3,"html":"선형함수를 활성화 함수로 사용할 경우 은닉층이 없는 네트워크로도 동일하게 표현할 수 있으므로, 인공신경망에서 층을 깊게 쌓는 의미가 약해진다."},{"n":4,"html":"시그모이드 함수를 활용할 경우 Gradient Vanishing(기울기 손실) 현상은 나타나지 않는다."}],"answer":[3]},{"id":"6a67532d1bbde79cd2c1c8db","number":61,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기에서 설명하고 있는 교차검증 방법은 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>주어진 데이터세트를 무작위(Random)로 서로 겹치지 않는 두 부분으로 나눈다.</li><li>한쪽은 모형의 학습과 구축에 쓰이는 훈련용 데이터로 활용한다.</li><li>나머지 한쪽은 성과평가에 쓰이는 검증용 데이터로 활용한다.</li><li>훈련 데이터세트로 분석모형을 만든 뒤, 검증용 데이터세트를 통해 해당 모형의 성능을 평가한다.</li><li>훈련집합과 검증 집합의 비율은 50 : 50, 70 : 30 등으로 정한다.</li><li>검증용 데이터의 결과는 분류분석모형에 영향을 미치지 않으며, 오직 모형의 성과 측정 용도로만 쓰인다.</li></ul></div>","choices":[{"n":1,"html":"K-medoids 교차검증"},{"n":2,"html":"다중교차(K-fold)"},{"n":3,"html":"K-means 교차검증"},{"n":4,"html":"홀드아웃(Hold-out)"}],"answer":[4]},{"id":"6a67532d1bbde79cd2c1c8d8","number":62,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래는 혼동행렬(Confusion Matrix)을 나타낸 표이다. 이를 바탕으로 계산한 민감도(Sensitivity)와 정밀도(Precision)의 값이 올바르게 짝지어진 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl is-center\"><tr><th colspan=\"2\" rowspan=\"2\">구 분</th><th colspan=\"2\">실제 범주 값</th></tr><tr><th>Yes(참)</th><th>No(거짓)</th></tr><tr><th rowspan=\"2\">예측 범주 값</th><th>Yes(참)</th><td>O(TP, True Positive), TP=12</td><td>X(FP, False Positive), FP=6</td></tr><tr><th>No(거짓)</th><td>X(FN, False Negative), FN=3</td><td>O(TN, True Negative), TN=15</td></tr></table></div>","choices":[{"n":1,"html":"민감도=2/7, 정밀도=5/7"},{"n":2,"html":"민감도=4/5, 정밀도=2/3"},{"n":3,"html":"민감도=5/7, 정밀도=2/7"},{"n":4,"html":"민감도=2/3, 정밀도=4/5"}],"answer":[2]},{"id":"6a67532d1bbde79cd2c1c8da","number":63,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>예측 모형의 예측오차(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub></mrow></semantics></math></span>)를 측정하는 지표 중 하나인 평균절대백분오차비율(MAPE, Mean Absolute Percentage Error)의 계산식으로 올바른 것은?</p>","choices":[{"n":1,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mi>n</mi></mfrac><mo>∑</mo><mo stretchy=\"false\">(</mo><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></semantics></math></span>"},{"n":2,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mi>n</mi></mfrac><mo>∑</mo><mrow><mo fence=\"true\">∣</mo><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub><mo fence=\"true\">∣</mo></mrow></mrow></semantics></math></span>"},{"n":3,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><mfrac><mn>1</mn><mi>n</mi></mfrac><mo>∑</mo><mrow><mo fence=\"true\">∣</mo><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub><mo fence=\"true\">∣</mo></mrow></mrow></msqrt></mrow></semantics></math></span>"},{"n":4,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mi>n</mi></mfrac><mo>∑</mo><mrow><mo fence=\"true\">∣</mo><mfrac><mrow><msub><mi>y</mi><mi>i</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo stretchy=\"true\">^</mo></mover><mi>i</mi></msub></mrow><msub><mi>y</mi><mi>i</mi></msub></mfrac><mo fence=\"true\">∣</mo></mrow></mrow></semantics></math></span>"}],"answer":[4]},{"id":"6a67532d1bbde79cd2c1c8e8","number":64,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>특정 통계 수치를 바탕으로 지도의 면적을 왜곡시켜 표현하는 시각화 기법으로, 지도에 의한 비교 통계도라고도 불리는 것은 무엇인가?</p>","choices":[{"n":1,"html":"Star Chart(스타 차트)"},{"n":2,"html":"Heat Map(히트맵)"},{"n":3,"html":"Cartogram(카토그램)"},{"n":4,"html":"Point Map(포인트 맵)"}],"answer":[3]},{"id":"6a67532d1bbde79cd2c1c8e1","number":65,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 로지스틱 회귀분석(Logistic Regression Analysis)에 관한 설명 가운데 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"이항형과 다항형으로 구분되며, 이항형일 때는 두 개의 카테고리로 나눈다."},{"n":2,"html":"종속변수가 정규분포를 따르는 경우에 적용한다."},{"n":3,"html":"입력 데이터가 주어졌을 때 그 데이터의 분석결과가 특정 분류로 나누어지는 분류 기법에 적용이 가능하다."},{"n":4,"html":"종속변수가 두 개의 카테고리로 구분되어 있는 경우 조건부 확률은 이항분포를 따른다."}],"answer":[2]},{"id":"6a67532d1bbde79cd2c1c8d9","number":66,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 ROC(Receiver Operating Characteristic) 곡선 및 AUC(Area under the Curve)에 관한 설명 중 옳지 않은 것을 고르시오.</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 540 470\" width=\"540\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ROC 곡선 비교 - 대각선 기준선 Model A, 그 위의 Model B, 가장 위의 Model C\"><defs><marker id=\"ah2\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"6.5\" markerHeight=\"6.5\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><line x1=\"70\" y1=\"420\" x2=\"486\" y2=\"420\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"70\" y1=\"420\" x2=\"70\" y2=\"26\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"70\" y1=\"420\" x2=\"70\" y2=\"427\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"170\" y1=\"420\" x2=\"170\" y2=\"427\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"270\" y1=\"420\" x2=\"270\" y2=\"427\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"370\" y1=\"420\" x2=\"370\" y2=\"427\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"470\" y1=\"420\" x2=\"470\" y2=\"427\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"70\" y=\"444\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">0</text><text x=\"170\" y=\"444\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">0.25</text><text x=\"270\" y=\"444\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">0.5</text><text x=\"370\" y=\"444\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">0.75</text><text x=\"470\" y=\"444\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">1</text><line x1=\"70\" y1=\"420\" x2=\"63\" y2=\"420\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"70\" y1=\"325\" x2=\"63\" y2=\"325\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"70\" y1=\"230\" x2=\"63\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"70\" y1=\"135\" x2=\"63\" y2=\"135\" stroke=\"currentColor\" stroke-width=\"1.2\"/><line x1=\"70\" y1=\"40\" x2=\"63\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"1.2\"/><text x=\"58\" y=\"425\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">0</text><text x=\"58\" y=\"330\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">0.25</text><text x=\"58\" y=\"235\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">0.5</text><text x=\"58\" y=\"140\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">0.75</text><text x=\"58\" y=\"45\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">1</text><text x=\"278\" y=\"464\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\">False-positive rate</text><text x=\"22\" y=\"225\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" transform=\"rotate(-90 22 225)\">True-positive rate(ROC)</text><path d=\"M70 420 L470 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-dasharray=\"2.5 5\"/><path d=\"M70 420 C110 250 230 110 470 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-dasharray=\"10 6\"/><path d=\"M70 420 C78 140 150 55 470 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"/><text x=\"118\" y=\"90\" font-size=\"16\" font-weight=\"700\" fill=\"currentColor\">Model C</text><line x1=\"190\" y1=\"94\" x2=\"180\" y2=\"107\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah2)\"/><text x=\"243\" y=\"176\" font-size=\"16\" font-weight=\"700\" fill=\"currentColor\">Model B</text><line x1=\"278\" y1=\"160\" x2=\"271\" y2=\"136\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah2)\"/><text x=\"338\" y=\"250\" font-size=\"16\" font-weight=\"700\" fill=\"currentColor\">Model A</text><line x1=\"366\" y1=\"234\" x2=\"352\" y2=\"164\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah2)\"/></svg></div>","choices":[{"n":1,"html":"Model A의 AUC 값보다 Model B의 AUC 값이 더 크다."},{"n":2,"html":"Model B보다 Model C의 성능이 더 우수하다."},{"n":3,"html":"기준선에 위치한 Model A가 성능 면에서 가장 뛰어나다."},{"n":4,"html":"AUC 값이 가장 큰 것은 Model C이다."}],"answer":[3]},{"id":"6a67532d1bbde79cd2c1c8e3","number":67,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>빅데이터 서비스(또는 비즈니스) 모델을 활용했을 때 기대되는 효과로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"공공분야에 도입할 경우 재난 예방은 물론 여러 분야에서 사회적 기회를 만들어낼 수 있다."},{"n":2,"html":"사회경제적 가치 측면에서 자동화된 알고리즘을 사용하여 의사결정 자동화와 비즈니스 혁신을 이룰 수 있다."},{"n":3,"html":"빅데이터 서비스를 활용하면 재택근무가 점차 줄어들게 된다."},{"n":4,"html":"정교한 의사결정에 도움이 되는 데이터 패턴 파악과 미래예측을 통한 효익 창출 등으로 수익을 늘릴 수 있다."}],"answer":[3]},{"id":"6a67532d1bbde79cd2c1c8e7","number":68,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음에서 설명하는 시각화 기법으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>서로 다른 변수들 간에 존재하는 연관성을 표현</li><li>광고비 지출액과 매출액 사이의 관련성 표현</li><li>스캐터 플롯, 행렬, 버블 차트 활용</li></ul></div>","choices":[{"n":1,"html":"분포 시각화"},{"n":2,"html":"시공간 시각화"},{"n":3,"html":"비교 시각화"},{"n":4,"html":"관계 시각화"}],"answer":[4]},{"id":"6a67532d1bbde79cd2c1c8d7","number":69,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 표는 머신러닝 모델의 성능 평가를 위한 혼동행렬(Confusion Matrix)이다. 실제 긍정(Positive) 범주 가운데 모델이 긍정으로 정확히 예측(True Positive)한 비율[TP/(TP+FN)]을 가리키는 용어는 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl is-center\"><tr><th colspan=\"2\" rowspan=\"2\">구 분</th><th colspan=\"2\">예측 범주 값</th></tr><tr><th>Yes(참)</th><th>No(거짓)</th></tr><tr><th rowspan=\"2\">실제 범주 값</th><th>Yes(참)</th><td>O(TP, True Positive)</td><td>X(FN, False Negative)</td></tr><tr><th>No(거짓)</th><td>X(FP, False Positive)</td><td>O(TN, True Negative)</td></tr></table></div>","choices":[{"n":1,"html":"특이도(Specificity)"},{"n":2,"html":"재현율(Recall)"},{"n":3,"html":"정확도(Accuracy)"},{"n":4,"html":"정밀도(Precision)"}],"answer":[2]},{"id":"6a67532d1bbde79cd2c1c8e4","number":70,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>데이터 분석결과를 시각화하는 것에 관한 설명 중 가장 옳지 않은 것은?</p>","choices":[{"n":1,"html":"최근의 시각화 기술에서는 사용자와의 상호작용 조작이 가능하도록 데이터를 변경하거나 새로운 조작 기능을 더하는 방식으로 인터랙션 기능이 적용되고 있다."},{"n":2,"html":"데이터 시각화는 구조화, 시각화, 시각표현 단계로 진행되며, 구조화 단계에서는 데이터 분석결과를 사용하는 이용자에 맞춘 시나리오 작성과 스토리 구성 작업이 요구된다."},{"n":3,"html":"최근에는 방대한 양의 정보로부터 하나의 인사이트를 도출하기 위해 다양한 시각화 도구가 활용되고 있다."},{"n":4,"html":"일반적으로 데이터 분석결과를 시각화할 때 새로운 지표를 만들어 활용할 필요는 없다."}],"answer":[4]},{"id":"6a67532c1bbde79cd2c1c8d5","number":71,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>참/거짓, 양성/음성, 남성/여성처럼 두 가지 범주로 분류하는 이진분류기의 성능 평가에는 혼동행렬(Confusion Matrix)이 활용된다. 다음 중 혼동행렬을 기반으로 산출하는 성능 지표로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"정밀도(Precision)"},{"n":2,"html":"Mean Absolute Error(MAE)"},{"n":3,"html":"정분류율(Accuracy)"},{"n":4,"html":"오분류율(Error Rate)"}],"answer":[2]},{"id":"6a67532d1bbde79cd2c1c8d6","number":72,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 표는 머신러닝 모델의 성능 평가를 위해 만든 혼동행렬(Confusion Matrix)이다. 실제 부정(Negative)인 범주 가운데 부정으로 정확하게 예측된 비율[TN/(TN+FP)]을 가리키는 용어는 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl is-center\"><tr><th colspan=\"2\" rowspan=\"2\">구 분</th><th colspan=\"2\">예측 범주 값</th></tr><tr><th>Yes(참)</th><th>No(거짓)</th></tr><tr><th rowspan=\"2\">실제 범주 값</th><th>Yes(참)</th><td>O(TP, True Positive)</td><td>X(FN, False Negative)</td></tr><tr><th>No(거짓)</th><td>X(FP, False Positive)</td><td>O(TN, True Negative)</td></tr></table></div>","choices":[{"n":1,"html":"정밀도(Precision)"},{"n":2,"html":"특이도(Specificity)"},{"n":3,"html":"정확도(Accuracy)"},{"n":4,"html":"민감도(Sensitivity)"}],"answer":[2]},{"id":"6a67532d1bbde79cd2c1c8e5","number":73,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 보기 가운데 데이터 분석결과를 시각화하는 기법으로 보기 어려운 것은?</p>","choices":[{"n":1,"html":"레이더 차트(Radar Chart)"},{"n":2,"html":"체르노프 페이스(Chernoff Face)"},{"n":3,"html":"히트맵(Heat Map)"},{"n":4,"html":"원-핫 인코딩(One-hot Encoding)"}],"answer":[4]},{"id":"6a67532d1bbde79cd2c1c8dc","number":74,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>학습 데이터를 기반으로 교차 검증 방법을 활용하여 데이터 분석모형을 개발할 때, 다음 중 옳지 않은 설명은 무엇인가?</p>","choices":[{"n":1,"html":"홀드아웃 교차 검증 방법의 경우, 데이터세트를 훈련집합과 테스트 집합으로 나눌 때 무작위로 구분하여 분류한다."},{"n":2,"html":"테스트 데이터(Testing Set)와 검증 데이터(Validation Set)는 일반적으로 같아도 무방하다."},{"n":3,"html":"훈련, 테스트, 검증 데이터세트로 구분했다면, 분석모형의 구축에는 훈련 데이터세트를 이용한다."},{"n":4,"html":"다중교차 방법은 홀드아웃 방법과 달리 모든 데이터세트를 훈련 데이터와 테스트 데이터로 사용하기 때문에, 분석모형의 평가 결과가 비교적 편향되지 않는다."}],"answer":[2]},{"id":"6a67532d1bbde79cd2c1c8e2","number":75,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기의 설명에 각각 해당하는 데이터 분석 방법으로 알맞은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 뉴턴의 관성의 법칙에 의하면 관성은 물체의 질량(무게)에 정비례하며, 물체의 질량에 따른 관성을 예측하려고 한다. 또한 가속도의 법칙은 F=ma로 표현되는데, 여기서 F : 힘(물체에 변화를 일으키는 요인), m : 질량(물체의 무게), a : 가속도(물체가 겪게 되는 변화 또는 속도의 변화)이다. 다시 말해 물체에 가해지는 힘이 같다면(질량이 클수록) 가속도는 작아지고, 가속도가 크면 질량은 작다는 뜻이 담겨 있다. 동일한 힘(F)을 얻기 위하여 질량(m)에 따른 가속도(a) 값을 예측하고자 한다.</li><li>(나) 고객의 제품 구매 여부를 알아보고자 한다. 이를 위하여 회귀분석을 수행하며 종속변수로는 이진변수(1은 예, 0은 아니오)를 사용한다. 이와 같이 독립변수에 따라 종속변수(이진변수)를 추정할 때 사용되고, 주로 시그모이드(Sigmoid) 함수를 활용한다.</li></ul></div>","choices":[{"n":1,"html":"(가) 선형 회귀분석, (나) 로지스틱 회귀분석"},{"n":2,"html":"(가) 선형 회귀분석, (나) 시그모이드 회귀분석"},{"n":3,"html":"(가) 시그모이드 회귀분석, (나) 선형 회귀분석"},{"n":4,"html":"(가) 로지스틱 회귀분석, (나) 선형 회귀분석"}],"answer":[1]},{"id":"6a67532d1bbde79cd2c1c8e0","number":76,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 거래 데이터세트(Data Set)가 있을 때, 연관규칙 &#x27;오렌지, 사과 ⇒ 자몽&#x27;의 지지도와 신뢰도를 구하면 각각 얼마인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>{오렌지, 사과, 자몽}</li><li>{수박, 레몬}</li><li>{오렌지, 사과, 레몬, 자몽}</li><li>{딸기, 수박, 사과, 레몬}</li><li>{딸기, 수박, 레몬, 자몽}</li><li>{오렌지, 사과}</li></ul></div>","choices":[{"n":1,"html":"지지도=50%, 신뢰도=50%"},{"n":2,"html":"지지도=50%, 신뢰도=66%"},{"n":3,"html":"지지도=33%, 신뢰도=50%"},{"n":4,"html":"지지도=33%, 신뢰도=66%"}],"answer":[4]},{"id":"6a67532d1bbde79cd2c1c8dd","number":77,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>모집단이 특정 확률분포를 따른다는 가정이 타당한지를 검정하는 적합도 검정에서, 실제 관측도수(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>O</mi><mi>i</mi></msub></mrow></semantics></math></span>)와 확률분포에서 계산된 기대도수(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E</mi><mi>i</mi></msub></mrow></semantics></math></span>)를 이용해 구하는 카이제곱 검정통계량(<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>χ</mi><mn>2</mn></msup></mrow></semantics></math></span>)으로 옳은 것은?</p>","choices":[{"n":1,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mi>k</mi></mfrac><mo>∑</mo><mrow><mo fence=\"true\">∣</mo><msub><mi>O</mi><mi>i</mi></msub><mo>−</mo><msub><mi>E</mi><mi>i</mi></msub><mo fence=\"true\">∣</mo></mrow></mrow></semantics></math></span>"},{"n":2,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mfrac><mrow><mo stretchy=\"false\">(</mo><msub><mi>O</mi><mi>i</mi></msub><mo>−</mo><msub><mi>E</mi><mi>i</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow><msub><mi>E</mi><mi>i</mi></msub></mfrac></mrow></semantics></math></span>"},{"n":3,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mi>k</mi></mfrac><mo>∑</mo><mrow><mo fence=\"true\">∣</mo><mfrac><mrow><msub><mi>O</mi><mi>i</mi></msub><mo>−</mo><msub><mi>E</mi><mi>i</mi></msub></mrow><msub><mi>E</mi><mi>i</mi></msub></mfrac><mo fence=\"true\">∣</mo></mrow></mrow></semantics></math></span>"},{"n":4,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mo stretchy=\"false\">(</mo><msub><mi>O</mi><mi>i</mi></msub><mo>−</mo><msub><mi>E</mi><mi>i</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></semantics></math></span>"}],"answer":[2]},{"id":"6a67532d1bbde79cd2c1c8e6","number":78,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 보기 중 관계 시각화에 해당하는 기법은 무엇인가?</p>","choices":[{"n":1,"html":"파이 차트(Pie Chart)"},{"n":2,"html":"체르노프 페이스(Chernoff Face)"},{"n":3,"html":"히트맵(Heat Map)"},{"n":4,"html":"버블 차트(Bubble Chart)"}],"answer":[4]},{"id":"6a67532d1bbde79cd2c1c8de","number":79,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>인공신경망을 분석할 때 과적합을 방지하기 위한 방법으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"은닉층의 노드 수를 줄이기"},{"n":2,"html":"가중치를 조절하기"},{"n":3,"html":"학습률을 줄이기"},{"n":4,"html":"신경망의 노드 중 일부를 사용하지 않기"}],"answer":[3]},{"id":"6a67532d1bbde79cd2c1c8df","number":80,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>시계열 데이터를 구성하는 주요 성분(패턴)에 해당하지 않는 것은 무엇인가?</p>","choices":[{"n":1,"html":"계절성(Seasonality)"},{"n":2,"html":"규칙(Rules)"},{"n":3,"html":"추세(Trend)"},{"n":4,"html":"주기성(Cycle)"}],"answer":[2]}]};